package dev.industrialtechnology.space;
import net.minecraft.inventory.*;import net.minecraft.entity.player.*;import net.minecraft.item.ItemStack;import cpw.mods.fml.common.network.simpleimpl.*;import dev.industrialtechnology.core.IndustrialTechnology;
public final class SpaceContainer extends Container {
    public final TileSpaceMachine tile;public final EntitySpaceRocket rocket;private long lastAction=Long.MIN_VALUE,lastSend;
    public SpaceContainer(EntityPlayer p,TileSpaceMachine t){this(p,t,null);}public SpaceContainer(EntityPlayer p,EntitySpaceRocket r){this(p,r.control,r);}
    private SpaceContainer(EntityPlayer p,TileSpaceMachine t,EntitySpaceRocket r){tile=t;rocket=r;for(int i=0;i<12;i++){final int slot=i;addSlotToContainer(new Slot(t,i,8+i*25,132){@Override public boolean isItemValid(ItemStack s){return !(rocket!=null&&slot==0)&&tile.isItemValidForSlot(slot,s);}@Override public boolean canTakeStack(EntityPlayer player){return !(rocket!=null&&slot==0)&&super.canTakeStack(player);}});}for(int row=0;row<3;row++)for(int col=0;col<9;col++)addSlotToContainer(new Slot(p.inventory,col+row*9+9,8+col*18,154+row*18));for(int col=0;col<9;col++)addSlotToContainer(new Slot(p.inventory,col,8+col*18,214));}
    @Override public boolean canInteractWith(EntityPlayer p){if(rocket==null)return tile.isUseableByPlayer(p);return !rocket.isDead&&rocket.worldObj==p.worldObj&&p.getDistanceSqToEntity(rocket)<=(rocket.shuttle()?4096:100)&&(p.worldObj.isRemote||rocket.phase==EntitySpaceRocket.LANDED&&rocket.owner.equals(p.getUniqueID().toString()));}
    public void action(EntityPlayerMP p,int action,int value){if(!canInteractWith(p))return;long now=p.worldObj.getTotalWorldTime();if(lastAction!=Long.MIN_VALUE&&now-lastAction<4)return;lastAction=now;if(rocket!=null&&action==6)rocket.launchAgain(p);else tile.action(p,action,value);send(p);}
    @Override public void detectAndSendChanges(){super.detectAndSendChanges();if(tile.getWorldObj()==null||tile.getWorldObj().isRemote)return;long now=tile.getWorldObj().getTotalWorldTime();if(now-lastSend<10)return;lastSend=now;for(Object o:crafters)if(o instanceof EntityPlayerMP)send((EntityPlayerMP)o);}
    public void send(EntityPlayerMP p){IndustrialTechnology.network.sendTo(new SpaceState(windowId,tile.snapshot()),p);}
    @Override public ItemStack transferStackInSlot(EntityPlayer p,int index){if(index<0||index>=inventorySlots.size())return null;Slot slot=(Slot)inventorySlots.get(index);if(!slot.getHasStack()||!slot.canTakeStack(p))return null;ItemStack s=slot.getStack(),old=s.copy();if(index<12){if(!mergeItemStack(s,12,48,true))return null;}else{boolean moved=false;for(int i=0;i<12&&s.stackSize>0;i++){Slot to=(Slot)inventorySlots.get(i);if(to.isItemValid(s)&&mergeItemStack(s,i,i+1,false))moved=true;}if(!moved)return null;}if(s.stackSize==0)slot.putStack(null);else slot.onSlotChanged();return old;}
}
